function reverseVowels(s) {
  const vowels = new Set('aeiouAEIOU');
  const chars = s.split('');
  let left = 0;
  let right = chars.length - 1;

  while (left < right) {
    if (!vowels.has(chars[left])) {
      left++;
    } else if (!vowels.has(chars[right])) {
      right--;
    } else {
      const temp = chars[left];
      chars[left] = chars[right];
      chars[right] = temp;
      left++;
      right--;
    }
  }
  return chars.join('');
}

