function reverseVowels(s) {
  const isVowel = c => 'aeiouAEIOU'.indexOf(c) !== -1;
  const found = [];
  for (const c of s) if (isVowel(c)) found.push(c);
  let result = '';
  for (const c of s) result += isVowel(c) ? found.pop() : c;
  return result;
}

