function generate(rand, size) {
  const printable = () => String.fromCharCode(32 + Math.floor(rand() * 95));
  const vowels = 'aeiouAEIOU';
  const letters = 'bcdyBCDYxz';
  const pick = text => text[Math.floor(rand() * text.length)];
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const vowelShare = rand();
  let s = '';
  for (let i = 0; i < n; i++) {
    const roll = rand();
    s += roll < vowelShare ? pick(vowels) : roll < vowelShare + (1 - vowelShare) / 2 ? pick(letters) : printable();
  }
  return [s];
}
